"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[98382],{73435:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>o,contentTitle:()=>a,default:()=>c,frontMatter:()=>r,metadata:()=>i,toc:()=>d});var h=n(31085),s=n(71184);const r={sidebar_position:12,slug:"/bible/Mark/Mark_12",title:"Mark 12",hide_table_of_contents:!0},a="Mark",i={id:"bible/Mark/Mark 12",title:"Mark 12",description:"Chapter 12",source:"@site/docs/bible/Mark/Mark 12.md",sourceDirName:"bible/Mark",slug:"/bible/Mark/Mark_12",permalink:"/docs/bible/Mark/Mark_12",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Mark/Mark 12.md",tags:[],version:"current",sidebarPosition:12,frontMatter:{sidebar_position:12,slug:"/bible/Mark/Mark_12",title:"Mark 12",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Mark 11",permalink:"/docs/bible/Mark/Mark_11"},next:{title:"Mark 13",permalink:"/docs/bible/Mark/Mark_13"}},o={},d=[{value:"Chapter 12",id:"chapter-12",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"mark",children:"Mark"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-12",children:"Chapter 12"}),"\n",(0,h.jsx)(t.p,{children:"The parable of the vineyard and husbandmen.  Caesar's right to tribute. The Sadducees are confuted.  The first commandment.  The widow's mite."}),"\n",(0,h.jsx)(n,{verse:1,children:"And he began to speak to them in parables: A certain man planted a vineyard and made a hedge about it and dug a place for the winefat and built a tower and let it to husbandmen: and went into a far country."}),"\n",(0,h.jsx)(n,{verse:2,children:"And at the season he sent to the husbandmen a servant to receive of the husbandmen of the fruit of the vineyard."}),"\n",(0,h.jsx)(n,{verse:3,children:"Who, having laid hands on him, beat and sent him away empty."}),"\n",(0,h.jsx)(n,{verse:4,children:"And again he sent to them another servant: and him they wounded in the head and used him reproachfully."}),"\n",(0,h.jsx)(n,{verse:5,children:"And again he sent another, and him they killed: and many others, of whom some they beat, and others they killed."}),"\n",(0,h.jsx)(n,{verse:6,children:"Therefore, having yet one son, most dear to him, he also sent him unto them last of all, saying: They will reverence my son."}),"\n",(0,h.jsx)(n,{verse:7,children:"But the husbandmen said one to another: This is the heir. Come let us kill him and the inheritance shall be ours."}),"\n",(0,h.jsx)(n,{verse:8,children:"And laying hold on him, they killed him and cast him out of the vineyard."}),"\n",(0,h.jsx)(n,{verse:9,children:"What therefore will the lord of the vineyard do? He will come and destroy those husbandmen and will give the vineyard to others."}),"\n",(0,h.jsx)(n,{verse:10,children:"And have you not read this scripture, The stone which the builders rejected, the same is made the head of the corner:"}),"\n",(0,h.jsx)(n,{verse:11,children:"By the Lord has this been done, and it is wonderful in our eyes."}),"\n",(0,h.jsx)(n,{verse:12,children:"And they sought to lay hands on him: but they feared the people. For they knew that he spoke this parable to them. And leaving him, they went their way."}),"\n",(0,h.jsx)(n,{verse:13,children:"And they sent to him some of the Pharisees and of the Herodians: that they should catch him in his words."}),"\n",(0,h.jsx)(n,{verse:14,children:"Who coming, say to him: Master, we know that thou art a true speaker and carest not for any man; for thou regardest not the person of men, but teachest the way of God in truth. Is it lawful to give tribute to Caesar? Or shall we not give it?"}),"\n",(0,h.jsx)(n,{verse:15,children:"Who knowing their wiliness, saith to them: Why tempt you me? Bring me a penny that I may see it."}),"\n",(0,h.jsx)(n,{verse:16,children:"And they brought it him. And he saith to them: Whose is this image and inscription? They say to him, Caesar's."}),"\n",(0,h.jsx)(n,{verse:17,children:"And Jesus answering, said to them: Render therefore to Caesar the things that are Caesar's and to God the things that are God's. And they marvelled at him."}),"\n",(0,h.jsx)(n,{verse:18,children:"And there came to him the Sadducees, who say there is no resurrection. And they asked him, saying:"}),"\n",(0,h.jsx)(n,{verse:19,children:"Master, Moses wrote unto us that if any man's brother die and leave his wife behind him and leave no children, his brother should take his wife and raise up seed to his brother."}),"\n",(0,h.jsx)(n,{verse:20,children:"Now there were seven brethren: and the first took a wife and died leaving no issue."}),"\n",(0,h.jsx)(n,{verse:21,children:"And the second took her and died: and neither did he leave any issue. And the third in like manner."}),"\n",(0,h.jsx)(n,{verse:22,children:"And the seven all took her in like manner and did not leave issue. Last of all the woman also died."}),"\n",(0,h.jsx)(n,{verse:23,children:"In the resurrection therefore, when they shall rise again, whose wife shall she be of them? For the seven had her to wife."}),"\n",(0,h.jsx)(n,{verse:24,children:"And Jesus answering, saith to them: Do ye not therefore err, because you know not the scriptures nor the power of God?"}),"\n",(0,h.jsx)(n,{verse:25,children:"For when they shall rise again from the dead, they shall neither marry, nor be married, but are as the angels in heaven."}),"\n",(0,h.jsx)(n,{verse:26,children:"And as concerning the dead that they rise again have you not read in the book of Moses, how in the bush God spoke to him, saying: I am the God of Abraham and the God of Isaac and the God of Jacob?"}),"\n",(0,h.jsx)(n,{verse:27,children:"He is not the God of the dead, but of the living. You therefore do greatly err."}),"\n",(0,h.jsx)(n,{verse:28,children:"And there came one of the scribes that had heard them reasoning together, and seeing that he had answered them well, asked him which was the first commandment of all."}),"\n",(0,h.jsx)(n,{verse:29,children:"And Jesus answered him: The first commandment of all is, Hear, O Israel: the Lord thy God is one God."}),"\n",(0,h.jsx)(n,{verse:30,children:"And thou shalt love the Lord thy God with thy whole heart and with thy whole soul and with thy whole mind and with thy whole strength. This is the first commandment."}),"\n",(0,h.jsx)(n,{verse:31,children:"And the second is like to it: Thou shalt love thy neighbour as thyself. There is no other commandment greater than these."}),"\n",(0,h.jsx)(n,{verse:32,children:"And the scribe said to him: Well, Master, thou hast said in truth that there is one God and there is no other besides him."}),"\n",(0,h.jsx)(n,{verse:33,children:"And that he should be loved with the whole heart and with the whole understanding and with the whole soul and with the whole strength. And to love one's neighbour as one's self is a greater thing than all holocausts and sacrifices."}),"\n",(0,h.jsx)(n,{verse:34,children:"And Jesus seeing that he had answered wisely, said to him: Thou art not far from the kingdom of God. And no man after that durst ask him any question."}),"\n",(0,h.jsx)(n,{verse:35,children:"And Jesus answering, said, teaching in the temple: How do the scribes say that Christ is the son of David?"}),"\n",(0,h.jsx)(n,{verse:36,children:"For David himself saith by the Holy Ghost: The Lord said to my Lord: Sit on my right hand, until I make thy enemies thy footstool."}),"\n",(0,h.jsx)(n,{verse:37,children:"David therefore himself calleth him Lord. And whence is he then his son? And a great multitude heard him gladly."}),"\n",(0,h.jsx)(n,{verse:38,children:"And he said to them in his doctrine: Beware of the scribes, who love to walk in long robes and to be saluted in the marketplace,"}),"\n",(0,h.jsx)(n,{verse:39,children:"And to sit in the first chairs in the synagogues and to have the highest places at suppers:"}),"\n",(0,h.jsx)(n,{verse:40,children:"Who devour the houses of widows under the pretence of long prayer. These shall receive greater judgment."}),"\n",(0,h.jsx)(n,{verse:41,children:"And Jesus sitting over against the treasury, beheld how the people cast money into the treasury. And many that were rich cast in much."}),"\n",(0,h.jsx)(n,{verse:42,children:"And there came a certain poor widow: and she cast in two mites, which make a farthing."}),"\n",(0,h.jsx)(n,{verse:43,children:"And calling his disciples together, he saith to them: Amen I say to you, this poor widow hath cast in more than all they who have cast into the treasury."}),"\n",(0,h.jsx)(n,{verse:44,children:"For all they did cast in of their abundance; but she of her want cast in all she had, even her whole living."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>i});var h=n(14041);const s={},r=h.createContext(s);function a(e){const t=h.useContext(r);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),h.createElement(r.Provider,{value:t},e.children)}}}]);